toolCalls.argumentsJson:
{
  "query" : "Funds transferred in and out of an account on the same day or within a relatively short period of time",
  "max_results" : 3
}

{
  "query" : "many different senders paying one account within a few days",
  "max_results" : 8
}

{
  "description" : "one account receives many incoming wire transfers from different external senders within a few days, with no prior activity and no outgoing payments"
}

{
  "alert_id" : "ALR-00003",
  "priority" : 1,
  "justification" : "C1055 received 6 wires from 6 different external senders (EXT-2173, EXT-2053, EXT-2256, EXT-2273, EXT-2151, EXT-2313) totalling 12208.90 CAD between 2026-09-18 and 2026-09-21, each 1725.82 to 2381.14 CAD. No other activity on the account in the data (2026-09-01 to 2026-09-21), and no outflows. Fan-in of unrelated senders in a few days matches FINTRAC wire indicators. Raised from 2 to 1 pending customer information."
}

{
  "case_id" : "CAS-00003",
  "description" : "Obtain from the customer of C1055: purpose of the account, relationship to the six senders (EXT-2173, EXT-2053, EXT-2256, EXT-2273, EXT-2151, EXT-2313), and the source of the 12208.90 CAD received 2026-09-18 to 2026-09-21. Check whether funds have been paid onward after 2026-09-21.",
  "justification" : "Six unrelated senders wired similar amounts into a账户 with no prior activity and no outflows in the data. The tools cannot show the customer's identity, the purpose of the funds, or what happened after the alert, so these must be established to decide between legitimate receipts and a money-mule pattern."
}
